package editdistance

import "testing"

func TestBothEmpty(t *testing.T) {
	if got := EditDistance("", ""); got != 0 {
		t.Errorf("EditDistance(\"\",\"\") = %d, want 0", got)
	}
}

func TestEqual(t *testing.T) {
	if got := EditDistance("abc", "abc"); got != 0 {
		t.Errorf("EditDistance(abc,abc) = %d, want 0", got)
	}
}

func TestKittenSitting(t *testing.T) {
	if got := EditDistance("kitten", "sitting"); got != 3 {
		t.Errorf("EditDistance(kitten,sitting) = %d, want 3", got)
	}
}

func TestHorseRos(t *testing.T) {
	if got := EditDistance("horse", "ros"); got != 3 {
		t.Errorf("EditDistance(horse,ros) = %d, want 3", got)
	}
}
